"use client";

import { useState } from "react";
import { useAIAgent } from "@/hooks/useAIAgent";
import { AudioPlayer } from "./AudioPlayer";
import {
  Bot,
  Mic,
  Sparkles,
  AlertCircle,
  Play,
  CheckCircle2,
  Loader2,
  Square,
  Radio,
  RadioTower,
  Cpu,
  ChevronDown,
  ChevronUp,
  ShieldAlert,
  Clock,
} from "lucide-react";

interface AIAgentPanelProps {
  meetingId: string;
  meetingTitle?: string;
}

export default function AIAgentPanel({ meetingId, meetingTitle }: AIAgentPanelProps) {
  const {
    agent,
    actionItems,
    citations,
    highlightedChunkIndex,
    setHighlightedChunkIndex,
    loading,
    errorMsg,
    userRole,
    customMeetUrl,
    setCustomMeetUrl,
    audioQuality,
    setAudioQuality,
    isTabRecording,
    tabRecordSeconds,
    handleManagedBotJoin,
    handleEndMeeting,
    startTabAudioCapture,
    stopTabAudioCapture,
  } = useAIAgent(meetingId);

  const [showAdvancedOptions, setShowAdvancedOptions] = useState(false);
  const [seekTimestamp, setSeekTimestamp] = useState<number | null>(null);

  // Convert mm:ss or timestamp string to seconds
  const parseTimestampToSeconds = (ts: string): number => {
    const parts = ts.replace(/[\[\]]/g, "").split(":");
    if (parts.length === 2) {
      return parseInt(parts[0], 10) * 60 + parseInt(parts[1], 10);
    }
    return 0;
  };

  const handleTranscriptClick = (timestamp: string, index: number) => {
    setHighlightedChunkIndex(index);
    const secs = parseTimestampToSeconds(timestamp);
    setSeekTimestamp(secs);
  };

  // Timeline Step Configurations
  const timelineSteps = [
    { key: "joining", label: "DISPATCHED", icon: Cpu, time: agent.joinedAt ? new Date(agent.joinedAt).toLocaleTimeString() : "--:--" },
    { key: "admitted", label: "ADMITTED", icon: CheckCircle2, time: agent.joinedAt ? new Date(agent.joinedAt).toLocaleTimeString() : "--:--" },
    { key: "recording", label: "RECORDING", icon: Radio, time: isTabRecording ? `${tabRecordSeconds}s` : "Active" },
    { key: "transcribing", label: "TRANSCRIBING", icon: Loader2, time: "Processing" },
    { key: "completed", label: "INSIGHTS READY", icon: Sparkles, time: "Complete" },
  ];

  const getCurrentStepIndex = () => {
    switch (agent.status) {
      case "joining": return 0;
      case "recording": return 2;
      case "transcribing":
      case "summarizing": return 3;
      case "completed": return 4;
      default: return -1;
    }
  };

  const currentStepIdx = getCurrentStepIndex();

  return (
    <div className="space-y-6 text-[var(--text)] font-sans">
      {/* CARD 1: Unified Meeting Controls & Status Timeline */}
      <div className="rounded-xl border border-[var(--border)] bg-[var(--panel)] p-5 shadow-sm space-y-5">
        {/* Card Header */}
        <div className="flex flex-wrap items-center justify-between gap-3 border-b border-[var(--border)] pb-4">
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-[var(--primary)]/10 border border-[var(--primary)]/30 text-[var(--primary)]">
              <Bot className="w-5 h-5" />
            </div>
            <div>
              <h3 className="font-display font-bold text-sm tracking-wider text-[var(--text)] uppercase">
                INNOVEXA AI MEETING ENGINE
              </h3>
              <p className="font-mono text-[11px] text-[var(--text-dim)] mt-0.5">
                Meeting ID: <span className="text-[var(--primary)] font-bold">{meetingId}</span>
              </p>
            </div>
          </div>

          {(agent.status === "joining" || agent.status === "recording" || isTabRecording) && (
            <button
              onClick={handleEndMeeting}
              disabled={loading}
              className="px-4 py-2 rounded-lg font-mono text-xs font-bold uppercase tracking-wider bg-[var(--red)] text-white hover:bg-[var(--red)]/90 transition-all flex items-center gap-2 shadow-sm"
            >
              {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Square className="w-4 h-4 fill-current" />}
              <span>END MEETING</span>
            </button>
          )}
        </div>

        {/* Vertical Chronological Status Timeline */}
        <div className="p-4 rounded-lg bg-[var(--panel-alt)] border border-[var(--border)] space-y-3">
          <div className="font-mono text-xs text-[var(--text-dim)] uppercase font-bold flex items-center gap-1.5 border-b border-[var(--border)] pb-2">
            <Clock className="w-4 h-4 text-[var(--primary)]" />
            <span>SESSION CHRONOLOGICAL STATUS TIMELINE</span>
          </div>

          <div className="grid grid-cols-2 sm:grid-cols-5 gap-2 pt-2">
            {timelineSteps.map((step, idx) => {
              const isPast = idx <= currentStepIdx;
              const isCurrent = idx === currentStepIdx;
              const StepIcon = step.icon;

              return (
                <div
                  key={step.key}
                  className={`p-2.5 rounded-lg border font-mono text-xs space-y-1 transition-all ${
                    isCurrent
                      ? "bg-[var(--primary)]/10 border-[var(--primary)] text-[var(--primary)] shadow-sm font-bold animate-pulse"
                      : isPast
                      ? "bg-[var(--panel)] border-[var(--teal)]/40 text-[var(--teal)] font-bold"
                      : "bg-[var(--panel)] border-[var(--border)] text-[var(--text-faint)]"
                  }`}
                >
                  <div className="flex items-center justify-between text-[10px]">
                    <span className="font-bold">STEP {idx + 1}</span>
                    <StepIcon className={`w-3.5 h-3.5 ${isCurrent ? "animate-spin" : ""}`} />
                  </div>
                  <div className="font-bold tracking-wider text-[11px]">{step.label}</div>
                  <div className="text-[10px] opacity-75">{step.time}</div>
                </div>
              );
            })}
          </div>
        </div>

        {/* Streamlined Primary Action Flow */}
        <div className="space-y-3 p-4 rounded-lg bg-[var(--panel-alt)] border border-[var(--border)]">
          <div className="flex items-center justify-between">
            <div className="font-mono text-xs text-[var(--primary)] font-bold uppercase flex items-center gap-1.5">
              <Cpu className="w-4 h-4" /> PRIMARY BOT ACTION FLOW
            </div>
            <button
              onClick={() => setShowAdvancedOptions(!showAdvancedOptions)}
              className="text-xs font-mono text-[var(--text-dim)] hover:text-[var(--primary)] transition-colors flex items-center gap-1"
            >
              <span>ADVANCED OPTIONS</span>
              {showAdvancedOptions ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
            </button>
          </div>

          <div className="flex flex-col sm:flex-row items-center gap-3">
            <input
              type="text"
              placeholder="Enter Google Meet URL (e.g. https://meet.google.com/qfz-imot-oic)"
              value={customMeetUrl}
              onChange={(e) => setCustomMeetUrl(e.target.value)}
              className="flex-1 w-full px-3.5 py-2.5 rounded-lg bg-[var(--panel)] border border-[var(--border)] text-xs font-mono text-[var(--text)] placeholder-[var(--text-faint)] focus:outline-none focus:border-[var(--primary)]"
            />
            <button
              onClick={handleManagedBotJoin}
              disabled={agent.status !== "idle" && agent.status !== "completed" || loading || userRole !== "organizer"}
              className="w-full sm:w-auto px-6 py-2.5 rounded-lg font-mono text-xs font-bold uppercase tracking-wider bg-[var(--primary)] text-white hover:bg-[var(--primary-hover)] transition-all disabled:opacity-40 disabled:cursor-not-allowed flex items-center justify-center gap-2 shadow-sm"
            >
              {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <Bot className="w-4 h-4" />}
              <span>LAUNCH AI MEETING ENGINE</span>
            </button>
          </div>

          {/* Expandable Advanced Options Drawer */}
          {showAdvancedOptions && (
            <div className="mt-4 pt-4 border-t border-[var(--border)] grid grid-cols-1 sm:grid-cols-2 gap-4 animate-fadeIn">
              {/* Option 1 Fallback */}
              <div className="p-3 rounded-lg bg-[var(--panel)] border border-[var(--border)] space-y-2">
                <div className="font-mono text-[10px] font-bold uppercase text-[var(--teal)] flex items-center gap-1">
                  <Radio size={12} /> TAB AUDIO RECORDING FALLBACK
                </div>
                {isTabRecording ? (
                  <button
                    onClick={stopTabAudioCapture}
                    className="w-full py-2 px-3 rounded font-mono text-xs font-bold bg-[var(--red)] text-white hover:bg-[var(--red)]/80 transition-all flex items-center justify-center gap-2 animate-pulse shadow-xs"
                  >
                    <Square className="w-3.5 h-3.5 fill-current" /> STOP TAB RECORDING ({tabRecordSeconds}s)
                  </button>
                ) : (
                  <button
                    onClick={startTabAudioCapture}
                    disabled={agent.status !== "idle" && agent.status !== "completed"}
                    className="w-full py-2 px-3 rounded font-mono text-xs font-bold uppercase tracking-wider bg-[var(--teal)] text-white hover:bg-[var(--teal)]/80 transition-all disabled:opacity-40 flex items-center justify-center gap-2 shadow-xs"
                  >
                    <Mic className="w-4 h-4" /> START TAB AUDIO RECORDING
                  </button>
                )}
              </div>

              {/* Quality Profile Selector */}
              <div className="p-3 rounded-lg bg-[var(--panel)] border border-[var(--border)] space-y-2">
                <div className="font-mono text-[10px] font-bold uppercase text-[var(--text-dim)] flex items-center gap-1">
                  <RadioTower size={12} /> SELECT AUDIO QUALITY PROFILE
                </div>
                <div className="flex items-center gap-1">
                  {(["high", "medium", "low"] as const).map((q) => (
                    <button
                      key={q}
                      onClick={() => setAudioQuality(q)}
                      className={`flex-1 py-1.5 rounded font-mono text-[11px] font-bold uppercase transition-all ${
                        audioQuality === q
                          ? "bg-[var(--primary)] text-white border border-[var(--primary)] font-bold shadow-xs"
                          : "bg-[var(--panel-alt)] text-[var(--text-dim)] border border-[var(--border)] hover:text-[var(--text)]"
                      }`}
                    >
                      {q === "high" ? "High (128k)" : q === "medium" ? "Med (64k)" : "Low (32k)"}
                    </button>
                  ))}
                </div>
              </div>
            </div>
          )}
        </div>

        {/* Host Admission Required Banner */}
        {(agent.status === "joining" || agent.status === "recording") && (
          <div className="rounded-lg bg-[var(--amber)]/12 border border-[var(--amber)]/40 p-3 text-[var(--amber)] text-xs flex items-center gap-2 font-mono">
            <Bot className="w-4 h-4 flex-shrink-0 animate-bounce" />
            <span>
              <strong>📢 HOST ADMISSION REQUIRED:</strong> Innovexa Notetaker has been dispatched to your Google Meet room! Switch to your Google Meet tab and click <strong>"Admit"</strong> when the host popup appears.
            </span>
          </div>
        )}
      </div>

      {/* CARD 2: Synced Live Transcript & Audio Waveform Player */}
      <div className="rounded-xl border border-[var(--border)] bg-[var(--panel)] p-5 shadow-sm space-y-4">
        <div className="font-mono text-xs uppercase tracking-wider text-[var(--primary)] flex items-center gap-2 font-semibold">
          <Mic className="w-4 h-4 text-[var(--teal)]" /> LIVE DIARIZED CAPTION STREAM & AUDIO PLAYER
        </div>

        {/* Audio Waveform Player with Click-to-Seek */}
        {agent.recordingUrl && (
          <AudioPlayer src={agent.recordingUrl} seekTime={seekTimestamp} isRecording={agent.status === "recording" || isTabRecording} />
        )}

        {/* Diarized Transcript Feed */}
        {agent.transcript && agent.transcript.length > 0 ? (
          <div className="rounded-lg bg-[var(--panel-alt)] border border-[var(--border)] p-3 max-h-56 overflow-y-auto space-y-2 font-mono text-xs">
            {agent.transcript.map((seg, i) => (
              <button
                key={i}
                onClick={() => handleTranscriptClick(seg.timestamp, i)}
                aria-label={`Seek audio to timestamp ${seg.timestamp} for speaker ${seg.speaker}`}
                className={`w-full text-left flex items-start gap-2 border-b border-[var(--border)] pb-2 last:border-0 last:pb-0 p-2 rounded transition-all hover:bg-[var(--primary)]/10 ${
                  highlightedChunkIndex === i ? "bg-[var(--primary)]/15 border-[var(--primary)] text-[var(--text)] font-bold" : ""
                }`}
              >
                <span className="text-[var(--primary)] font-bold flex-shrink-0">[{seg.timestamp}] {seg.speaker}:</span>
                <span className="text-[var(--text)]">{seg.text}</span>
              </button>
            ))}
          </div>
        ) : (
          <div className="text-center py-6 border border-dashed border-[var(--border)] rounded-lg text-xs font-mono text-[var(--text-faint)]">
            No live transcript segments available. Launch bot or start tab recording to stream captions.
          </div>
        )}
      </div>

      {/* CARD 3: Executive AI Summary & Rationale */}
      {agent.summary && (
        <div className="rounded-xl border border-[var(--border)] bg-[var(--panel)] p-5 shadow-sm space-y-3">
          <div className="font-mono text-xs uppercase tracking-wider text-[var(--primary)] flex items-center gap-2 font-semibold border-b border-[var(--border)] pb-3">
            <Sparkles className="w-4 h-4 text-[var(--amber)]" /> EXECUTIVE AI SYNTHESIS & RATIONALE
          </div>
          <p className="text-sm text-[var(--text-dim)] leading-relaxed font-sans">{agent.summary}</p>
        </div>
      )}

      {/* CARD 4: Automated Action Items & Task Assignments */}
      {actionItems.length > 0 && (
        <div className="rounded-xl border border-[var(--border)] bg-[var(--panel)] p-5 shadow-sm space-y-4">
          <div className="font-mono text-xs uppercase tracking-wider text-[var(--teal)] flex items-center gap-2 font-semibold border-b border-[var(--border)] pb-3">
            <CheckCircle2 className="w-4 h-4 text-[var(--teal)]" /> AUTOMATED ACTION ITEMS & TASK ASSIGNMENTS
          </div>
          <div className="grid grid-cols-1 sm:grid-cols-2 gap-3">
            {actionItems.map((item, idx) => (
              <div key={idx} className="rounded-lg border border-[var(--border)] bg-[var(--panel-alt)] p-3 space-y-1.5 font-mono text-xs">
                <div className="flex items-center justify-between text-[var(--primary)]">
                  <span className="font-bold">{item.ownerName || item.assignee}</span>
                  <span className="text-[10px] px-2 py-0.5 rounded bg-[var(--teal)]/12 text-[var(--teal)] border border-[var(--teal)]/30 font-bold">
                    {item.priority || "Medium"}
                  </span>
                </div>
                <div className="text-[var(--text)] font-semibold text-xs">{item.title || item.task}</div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* Actionable Error Banner */}
      {errorMsg && (
        <div className="rounded-lg bg-[var(--red)]/12 border border-[var(--red)]/40 p-4 text-[var(--red)] text-xs flex items-center gap-3 font-mono">
          <AlertCircle className="w-5 h-5 flex-shrink-0" />
          <span>{errorMsg}</span>
        </div>
      )}
    </div>
  );
}

meetBot.js.content:
const { chromium } = require("playwright");
const { PulseAudio } = require("./pulseaudio");
const logger = require("./logger");
const config = require("./config");
const metrics = require("./metrics");

/**
 * Progressive Exponential Backoff Delay with Jitter
 */
function getExponentialBackoffDelay(attempt, initialMs = config.retry.initialBackoffMs, factor = config.retry.backoffFactor, maxMs = config.retry.maxBackoffMs) {
  const delay = Math.min(initialMs * Math.pow(factor, attempt), maxMs);
  const jitter = delay * 0.1 * Math.random();
  return Math.round(delay + jitter);
}

class MeetBot {
  async join(meetingUrl, botName = config.bot.name) {
    const startTime = Date.now();
    metrics.recordSessionStart();
    logger.info("Initiating MeetBot join task", { stage: "JOIN_INITIATED", meetingUrl, botName });

    const pulseAudio = new PulseAudio();
    try {
      await pulseAudio.setupSink();
    } catch (e) {
      logger.warn("PulseAudio sink pre-setup skipped or unavailable:", { error: e.message });
    }

    const launchOptions = {
      headless: process.env.HEADLESS !== "false",
      args: [
        "--use-fake-ui-for-media-stream",
        "--disable-blink-features=AutomationControlled",
        "--no-sandbox",
        "--disable-setuid-sandbox",
        "--mute-audio=false",
      ],
      env: {
        ...process.env,
        PULSE_SERVER: process.env.PULSE_SERVER || "unix:/tmp/pulse-socket/pulse-socket",
        PULSE_SINK: process.env.PULSE_SINK || "MeetSink",
        DISPLAY: process.env.DISPLAY || ":99",
      },
    };

    if (process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH) {
      launchOptions.executablePath = process.env.PLAYWRIGHT_CHROMIUM_EXECUTABLE_PATH;
    }

    const browser = await chromium.launch(launchOptions);
    this.browser = browser;

    const context = await browser.newContext({
      permissions: ["microphone", "camera"],
      viewport: { width: 1280, height: 720 },
    });

    const page = await context.newPage();
    this.page = page;
    let audioFile = null;

    try {
      logger.info("Navigating to Google Meet URL", { meetingUrl });
      await page.goto(meetingUrl, { waitUntil: "domcontentloaded", timeout: 45000 });

      // Wait for Google Meet lobby UI to load instantly
      await page.waitForTimeout(500);

      // 1. Handle guest name input if present
      try {
        const nameSelectors = [
          'input[aria-label*="name" i]',
          'input[placeholder*="name" i]',
          'input[type="text"]'
        ];
        for (const selector of nameSelectors) {
          const input = await page.$(selector);
          if (input && (await input.isVisible().catch(() => false))) {
            await input.fill(botName);
            logger.info("Entered bot name as guest", { botName, selector });
            await page.waitForTimeout(100);
            break;
          }
        }
      } catch (e) {
        logger.debug("Guest name input check skipped", { error: e.message });
      }

      // 2. Mute camera and microphone
      try {
        await page.keyboard.press("Control+d");
        await page.keyboard.press("Control+e");
      } catch (e) { /* ignore */ }

      try {
        const camBtn = page.getByRole("button", { name: /turn off camera/i });
        if (await camBtn.isVisible({ timeout: 500 }).catch(() => false)) {
          await camBtn.click().catch(() => {});
        }
      } catch (e) { /* ignore */ }

      try {
        const micBtn = page.getByRole("button", { name: /turn off microphone/i });
        if (await micBtn.isVisible({ timeout: 500 }).catch(() => false)) {
          await micBtn.click().catch(() => {});
        }
      } catch (e) { /* ignore */ }

      logger.info("Disabled camera and microphone");

      // 3. Click "Ask to join" or "Join now" with resilient multi-selector retry loop
      let clicked = false;
      const joinSelectors = [
        'button:has-text("Ask to join")',
        'button:has-text("Join now")',
        'button[aria-label*="Ask to join" i]',
        'button[aria-label*="Join now" i]',
        'div[role="button"]:has-text("Ask to join")',
        'div[role="button"]:has-text("Join now")',
        'button[data-id]',
        'button[jsname]'
      ];

      for (let attempt = 0; attempt < 5; attempt++) {
        for (const sel of joinSelectors) {
          try {
            const btn = await page.$(sel);
            if (btn && (await btn.isVisible().catch(() => false))) {
              await btn.click({ force: true });
              clicked = true;
              logger.info(`Successfully clicked join button via selector: ${sel}`);
              break;
            }
          } catch (e) { /* ignore */ }
        }
        if (clicked) break;
        const delay = getExponentialBackoffDelay(attempt, 300, 1.5, 2000);
        await page.waitForTimeout(delay);
      }

      if (!clicked) {
        logger.info("Attempting robust JS DOM injection fallback for Google Meet join button...");
        clicked = await page.evaluate(() => {
          const els = Array.from(document.querySelectorAll('button, div[role="button"], span[role="button"]'));
          const btn = els.find((el) => {
            const txt = (el.textContent || "").toLowerCase();
            const aria = (el.getAttribute("aria-label") || "").toLowerCase();
            const jsname = el.getAttribute("jsname");
            return (
              txt.includes("ask to join") ||
              txt.includes("join now") ||
              aria.includes("ask to join") ||
              aria.includes("join now") ||
              jsname === "QYrYVd" ||
              jsname === "CQYiBc"
            );
          });
          if (btn) {
            btn.click();
            return true;
          }
          return false;
        }).catch(() => false);

        if (clicked) {
          logger.info("Successfully clicked join button via JS DOM injection!");
        }
      }

      if (!clicked) {
        logger.warn("Primary & JS injection selectors missed, attempting direct ENTER key press...");
        await page.keyboard.press("Enter");
      }

      // Wait for admission
      await this.waitForAdmission(page);
      const joinDurationMs = Date.now() - startTime;
      metrics.recordJoinSuccess(joinDurationMs);
      logger.info("Bot admitted to meeting call", { stage: "ADMITTED", joinDurationMs });

      const meetingId = meetingUrl.split("/").pop() || "session";

      // Context Awareness Audit Trail
      this.sessionContext = {
        meetingId,
        meetingUrl,
        joinedAt: new Date().toISOString(),
        admittedBy: "Host / Meeting Organizer",
        maxParticipantsSeen: 1,
        participantCountHistory: [],
        leaveReason: null,
      };
      logger.info("[Context Audit] Bot session context initialized:", this.sessionContext);

      // Start Watchdog Health Monitoring
      this.startHealthWatchdog(page, meetingId);

      // Send consent message
      await this.sendConsentMessage(page);
      logger.info("Sent in-chat consent message");

      // Start audio capture with retry mechanism & MediaRecorder fallback
      try {
        audioFile = await pulseAudio.startRecording(meetingId);
        logger.info("Started primary PulseAudio sink recording", { audioFile });
      } catch (pulseErr) {
        logger.warn("PulseAudio sink failed, attempting 1 retry...", { error: pulseErr.message });
        try {
          await new Promise((r) => setTimeout(r, 1000));
          await pulseAudio.setupSink();
          audioFile = await pulseAudio.startRecording(meetingId);
          logger.info("PulseAudio retry succeeded!", { audioFile });
        } catch (retryErr) {
          logger.warn("PulseAudio retry failed. Activating browser MediaRecorder API fallback...", { error: retryErr.message });
          await page.evaluate(() => {
            try {
              window._mediaChunks = [];
              const ctx = new (window.AudioContext || window.webkitAudioContext)();
              const dest = ctx.createMediaStreamDestination();
              const els = document.querySelectorAll('audio, video');
              els.forEach(el => {
                try {
                  const src = ctx.createMediaElementSource(el);
                  src.connect(dest);
                  src.connect(ctx.destination);
                } catch (e) {}
              });
              const recorder = new MediaRecorder(dest.stream);
              recorder.ondataavailable = (e) => { if (e.data.size > 0) window._mediaChunks.push(e.data); };
              recorder.start(1000);
              window._mediaRecorder = recorder;
            } catch (e) { console.error('MediaRecorder fallback error:', e); }
          }).catch(() => {});
          audioFile = pulseAudio.createFailsafeRecording(meetingId);
        }
      }

      // Detect meeting end
      await this.waitForMeetingEnd(page);

    } catch (err) {
      metrics.recordSessionFailure(err.message);
      logger.error("MeetBot execution error", { stage: "SESSION_ERROR", error: err.message, meetingUrl });
      throw err;
    } finally {
      this.stopHealthWatchdog();
      logger.info("Stopping PulseAudio recording and closing browser...");
      try {
        audioFile = await pulseAudio.stopRecording();
      } catch (e) {
        logger.warn("PulseAudio stop recording error", { error: e.message });
      }
      await browser.close();
      logger.info("Browser session closed.");
    }

    return audioFile;
  }

  async waitForAdmission(page, timeoutMs = 5 * 60 * 1000) {
    const start = Date.now();
    let attemptCount = 0;
    logger.info("Waiting for host admission to meeting call...");
    while (Date.now() - start < timeoutMs) {
      // 1. URL parameter change check (e.g., ?pli=1, authuser=, or meeting join session params)
      const currentUrl = page.url();
      if (currentUrl.includes("pli=") || currentUrl.includes("authuser=") || currentUrl.includes("&hs=")) {
        logger.info("Admission detected via URL parameter change:", { currentUrl });
        return true;
      }

      // 2. Playwright element and button visibility check
      const inCall = await page.getByText(/you're presenting|leave call/i).isVisible().catch(() => false);
      if (inCall) return true;

      const leaveBtn = page.getByRole("button", { name: /leave call/i });
      if (await leaveBtn.isVisible().catch(() => false)) return true;

      // 3. DOM JS evaluation for in-call state or leave button
      const domInCall = await page.evaluate(() => {
        const url = window.location.href;
        if (url.includes("pli=") || url.includes("authuser=")) return true;
        const leave = document.querySelector('button[aria-label*="Leave call" i], button[jsname="CQYiBc"]');
        return !!leave;
      }).catch(() => false);

      if (domInCall) return true;

      const delay = getExponentialBackoffDelay(attemptCount++, 1000, 1.3, 4000);
      await page.waitForTimeout(delay);
    }
    throw new Error("The bot couldn't join because the host didn't admit it within 5 minutes. Please ensure a meeting organizer clicks 'Admit'.");
  }

  async sendConsentMessage(page) {
    try {
      const chatBtn = page.getByRole("button", { name: /chat/i });
      if (await chatBtn.isVisible({ timeout: 5000 }).catch(() => false)) {
        await chatBtn.click();
        await page.waitForTimeout(1000);
        const chatInput = page.getByRole("textbox", { name: /send a message/i });
        if (await chatInput.isVisible({ timeout: 5000 }).catch(() => false)) {
          const consentMsg = "This meeting is being recorded and transcribed by Innovexa. Reply STOP to object.";
          await chatInput.fill(consentMsg);
          await page.keyboard.press("Enter");
          logger.info("Sent consent message to meeting chat");
        }
      }
    } catch (e) {
      logger.warn("Send consent message step skipped", { error: e.message });
    }
  }

  async getParticipantCount(page) {
    try {
      const count = await page.evaluate(() => {
        const selectors = [
          'div[aria-label*="people" i]',
          'button[aria-label*="people" i]',
          'div[aria-label*="participants" i]',
          'button[aria-label*="participants" i]',
          'span.uGfcg',
          'div.wnU2fd',
        ];
        for (const sel of selectors) {
          const el = document.querySelector(sel);
          if (el) {
            const txt = el.getAttribute("aria-label") || el.textContent || "";
            const match = txt.match(/\d+/);
            if (match) return parseInt(match[0], 10);
          }
        }
        const tiles = document.querySelectorAll('div[data-participant-id]');
        if (tiles.length > 0) return tiles.length;
        return 1;
      }).catch(() => 1);
      return count || 1;
    } catch {
      return 1;
    }
  }

  async checkConsentObjections(page) {
    try {
      const objectionFound = await page.evaluate(() => {
        const msgs = Array.from(document.querySelectorAll('div[data-message-text], div[jsname="d1F9d"], div[role="listitem"]'));
        return msgs.some((m) => {
          const txt = (m.textContent || "").trim().toUpperCase();
          return txt === "STOP" || txt.includes("STOP RECORDING") || txt.includes("DO NOT RECORD") || txt.includes("I OBJECT");
        });
      }).catch(() => false);

      if (objectionFound) {
        logger.warn("[Consent Management] Participant objection received ('STOP'). Disconnecting bot gracefully...");
        if (this.sessionContext) {
          this.sessionContext.leaveReason = "Interactive Consent Objection: Participant requested STOP in meeting chat";
        }
        return true;
      }
      return false;
    } catch {
      return false;
    }
  }

  async waitForMeetingEnd(page) {
    logger.info("Initializing Smart End Detection loop (participant tracking & empty-room detection)...");
    const start = Date.now();
    const maxDuration = process.env.MAX_MEETING_DURATION_MS 
      ? parseInt(process.env.MAX_MEETING_DURATION_MS) 
      : 3600000;

    let aloneConsecutiveCount = 0;

    while (Date.now() - start < maxDuration) {
      if (!page || page.isClosed()) {
        logger.info("Page closed. Smart End loop exiting.");
        break;
      }

      // 1. Interactive Consent Objection Monitoring (STOP)
      const objection = await this.checkConsentObjections(page);
      if (objection) {
        logger.info("Smart End triggered: Participant STOP consent objection received.");
        break;
      }

      // 2. Check for explicit "You left" or "Meeting ended" text
      const leftDetected = await page.evaluate(() => {
        const txt = document.body ? document.body.innerText : "";
        return (
          txt.includes("You left the meeting") ||
          txt.includes("You've been removed from the meeting") ||
          txt.includes("Meeting ended for everyone")
        );
      }).catch(() => false);

      if (leftDetected) {
        if (this.sessionContext) this.sessionContext.leaveReason = "Explicit meeting end or ejection detected";
        logger.info(`Smart End triggered: Explicit disconnect`);
        break;
      }

      // 2. Participant Count Tracking & Empty Room Smart End
      const currentParticipants = await this.getParticipantCount(page);
      if (this.sessionContext) {
        this.sessionContext.participantCountHistory.push({ time: new Date().toISOString(), count: currentParticipants });
        if (currentParticipants > this.sessionContext.maxParticipantsSeen) {
          this.sessionContext.maxParticipantsSeen = currentParticipants;
        }
      }

      logger.info(`[Participant Count Tracker] Currently ${currentParticipants} active participant(s) in call (Peak: ${this.sessionContext ? this.sessionContext.maxParticipantsSeen : 1})`);

      if (currentParticipants <= 1 && this.sessionContext && this.sessionContext.maxParticipantsSeen > 1) {
        aloneConsecutiveCount++;
        logger.warn(`[Smart End Warning] Bot is alone in call (${aloneConsecutiveCount}/3 checks).`);
        if (aloneConsecutiveCount >= 3) {
          this.sessionContext.leaveReason = "Smart End: All human participants left meeting call";
          logger.info(`Smart End triggered: ${this.sessionContext.leaveReason}`);
          break;
        }
      } else {
        aloneConsecutiveCount = 0;
      }

      await page.waitForTimeout(10000).catch(() => {});
    }

    if (this.sessionContext) {
      logger.info("[Context Audit] Final Session Audit Summary:", this.sessionContext);
    }
  }

  async leave(retries = 3) {
    logger.info("Explicit leave signal received. Disconnecting bot from Google Meet...");
    try {
      if (this.page && !this.page.isClosed()) {
        const leaveSelectors = [
          'button[aria-label*="Leave call" i]',
          'button[aria-label*="Leave" i]',
          'button:has-text("Leave")',
          'button[jsname="CQYiBc"]',
          'div[role="button"][aria-label*="Leave" i]',
        ];

        let clicked = false;
        for (let r = 0; r < retries; r++) {
          for (const sel of leaveSelectors) {
            try {
              const btn = await this.page.$(sel);
              if (btn && (await btn.isVisible().catch(() => false))) {
                await btn.click({ force: true }).catch(() => {});
                clicked = true;
                logger.info(`Successfully clicked leave call button via selector: ${sel}`);
                break;
              }
            } catch (e) { /* ignore */ }
          }
          if (clicked) break;
          await this.page.waitForTimeout(500).catch(() => {});
        }

        if (!clicked) {
          logger.info("Selector retry loop missed. Attempting JS DOM evaluation for leave button...");
          clicked = await this.page.evaluate(() => {
            const btns = Array.from(document.querySelectorAll('button, div[role="button"], span[role="button"]'));
            const leaveBtn = btns.find((b) => {
              const txt = (b.textContent || "").toLowerCase();
              const aria = (b.getAttribute("aria-label") || "").toLowerCase();
              const jsname = b.getAttribute("jsname");
              return txt.includes("leave") || aria.includes("leave") || jsname === "CQYiBc";
            });
            if (leaveBtn) {
              leaveBtn.click();
              return true;
            }
            return false;
          }).catch(() => false);
        }

        if (!clicked) {
          logger.info("Attempting Google Meet keyboard shortcut fallback (Ctrl+E / Cmd+E)...");
          await this.page.keyboard.press("Control+e").catch(() => {});
          await this.page.keyboard.press("Meta+e").catch(() => {});
          await this.page.waitForTimeout(500).catch(() => {});
        }

        await this.page.close().catch(() => {});
      }

      this.stopHealthWatchdog();
      if (this.browser) {
        await this.browser.close().catch(() => {});
      }
      logger.info("Bot browser instance closed cleanly.");
    } catch (e) {
      logger.warn("Error during explicit bot leave execution:", { error: e.message });
      if (retries > 0) {
        await new Promise((resolve) => setTimeout(resolve, 500));
        return this.leave(retries - 1);
      }
    }
  }

  startHealthWatchdog(page, meetingId, intervalMs = 15000) {
    logger.info(`[Watchdog] Starting periodic health watchdog for meeting: ${meetingId} (interval: ${intervalMs}ms)`);
    this.watchdogTimer = setInterval(async () => {
      try {
        if (!page || page.isClosed()) {
          logger.warn(`[Watchdog] Page closed for meeting ${meetingId}. Stopping watchdog.`);
          this.stopHealthWatchdog();
          return;
        }

        const disconnectedOrEjected = await page.evaluate(() => {
          const bodyText = document.body ? document.body.innerText : "";
          return (
            bodyText.includes("You left the meeting") ||
            bodyText.includes("You've been removed from the meeting") ||
            bodyText.includes("Meeting ended for everyone") ||
            bodyText.includes("You can't join this call")
          );
        }).catch(() => false);

        if (disconnectedOrEjected) {
          logger.warn(`[Watchdog] Disconnect/Ejection event detected for meeting ${meetingId}! Triggering session cleanup.`);
          this.stopHealthWatchdog();
        } else {
          logger.info(`[Watchdog Check] Bot healthy and active in call for meeting ${meetingId}`);
        }
      } catch (err) {
        logger.warn(`[Watchdog Check Error] ${err.message}`);
      }
    }, intervalMs);
  }

  stopHealthWatchdog() {
    if (this.watchdogTimer) {
      clearInterval(this.watchdogTimer);
      this.watchdogTimer = null;
      logger.info("[Watchdog] Health watchdog monitor stopped cleanly.");
    }
  }
}

module.exports = { MeetBot };

useAIAgent.ts.content:
"use client";

import { useEffect, useState, useRef, useCallback } from "react";

export interface TranscriptSegment {
  speaker: string;
  text: string;
  timestamp: string;
}

export interface AIAgentData {
  id?: string;
  meetingId: string;
  status: "idle" | "joining" | "recording" | "transcribing" | "summarizing" | "completed";
  joinedAt?: string;
  recordingUrl?: string;
  transcript?: TranscriptSegment[];
  summary?: string;
}

export function useAIAgent(meetingId: string) {
  const [agent, setAgent] = useState<AIAgentData>({
    meetingId,
    status: "idle",
  });
  const [actionItems, setActionItems] = useState<any[]>([]);
  const [citations, setCitations] = useState<any[]>([]);
  const [highlightedChunkIndex, setHighlightedChunkIndex] = useState<number | null>(null);

  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);
  const [userRole, setUserRole] = useState<string>("organizer");
  const [customMeetUrl, setCustomMeetUrl] = useState("");
  const [audioQuality, setAudioQuality] = useState<"high" | "medium" | "low">("medium");

  // Live Tab Audio Capture State
  const [isTabRecording, setIsTabRecording] = useState(false);
  const [tabRecordSeconds, setTabRecordSeconds] = useState(0);
  const mediaRecorderRef = useRef<MediaRecorder | null>(null);
  const audioChunksRef = useRef<Blob[]>([]);
  const recordTimerRef = useRef<NodeJS.Timeout | null>(null);

  const eventSourceRef = useRef<EventSource | null>(null);
  const socketRef = useRef<WebSocket | null>(null);

  const fetchStatus = useCallback(async () => {
    try {
      const res = await fetch(`/api/ai-agent/status/${meetingId}`);
      if (res.ok) {
        const data = await res.json();
        setAgent(data);
      }
    } catch {
      // Ignore
    }
  }, [meetingId]);

  const fetchActionItems = useCallback(async () => {
    try {
      const res = await fetch(`/api/recordings/meeting/${meetingId}`);
      if (res.ok) {
        const data = await res.json();
        setActionItems(data.actionItems || []);
      }
    } catch {
      // Ignore
    }
  }, [meetingId]);

  const fetchCitations = useCallback(async () => {
    try {
      const res = await fetch(`/api/citations?meetingId=${meetingId}`);
      if (res.ok) {
        const data = await res.json();
        setCitations(data);
      }
    } catch (err) {
      console.warn("[useAIAgent] Mapped citations not found yet:", err);
    }
  }, [meetingId]);

  useEffect(() => {
    const role = sessionStorage.getItem("userRole") || "organizer";
    setUserRole(role);

    fetchStatus();
    fetchActionItems();
    fetchCitations();

    return () => {
      if (socketRef.current) socketRef.current.close();
      if (eventSourceRef.current) eventSourceRef.current.close();
      if (recordTimerRef.current) clearInterval(recordTimerRef.current);
    };
  }, [meetingId, fetchStatus, fetchActionItems, fetchCitations]);

  const handleManagedBotJoin = async () => {
    if (userRole !== "organizer") {
      setErrorMsg("Forbidden: Must be logged in as an Organizer.");
      return;
    }

    setLoading(true);
    setErrorMsg(null);
    try {
      let res = await fetch("/api/meeting-baas", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
          "x-user-role": userRole,
        },
        body: JSON.stringify({ meetingId, meetingUrl: customMeetUrl.trim() || undefined }),
      });

      if (!res.ok) {
        res = await fetch("/api/ai-agent/join", {
          method: "POST",
          headers: {
            "Content-Type": "application/json",
            "x-user-role": userRole,
          },
          body: JSON.stringify({ meetingId, meetingUrl: customMeetUrl.trim() || undefined, useManagedBot: true }),
        });
      }

      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error || "Failed to trigger AI Agent");
      }

      const data = await res.json();
      setAgent(data);
    } catch (err: unknown) {
      const msg = err instanceof Error ? err.message : "Error joining meeting";
      setErrorMsg(msg);
    } finally {
      setLoading(false);
    }
  };

  const uploadAndProcessTabAudio = async (audioBlob: Blob) => {
    setAgent((prev) => ({ ...prev, status: "transcribing" }));
    try {
      const formData = new FormData();
      formData.append("audio", audioBlob, `meeting_tab_${Date.now()}.webm`);
      formData.append("meetingId", meetingId);

      const res = await fetch("/api/recordings/upload", {
        method: "POST",
        headers: { "x-user-role": userRole },
        body: formData,
      });

      if (!res.ok) {
        const err = await res.json();
        throw new Error(err.error || "Failed to process audio recording");
      }

      const data = await res.json();
      setAgent(data.agent || data);
      await fetchStatus();
      await fetchActionItems();
      await fetchCitations();
    } catch (err: any) {
      console.error("Tab audio upload error:", err);
      setErrorMsg(err.message || "Failed to upload audio recording.");
      setAgent((prev) => ({ ...prev, status: "idle" }));
    }
  };

  const startTabAudioCapture = async () => {
    setErrorMsg(null);
    try {
      audioChunksRef.current = [];
      let stream: MediaStream;
      try {
        stream = await navigator.mediaDevices.getDisplayMedia({
          video: true,
          audio: {
            echoCancellation: true,
            noiseSuppression: true,
          } as any,
        });
      } catch {
        stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      }

      const targetBitrate = audioQuality === "high" ? 128000 : audioQuality === "low" ? 32000 : 64000;
      const recorder = new MediaRecorder(stream, { audioBitsPerSecond: targetBitrate });
      mediaRecorderRef.current = recorder;

      let chunkIndex = 0;
      recorder.ondataavailable = (event) => {
        if (event.data && event.data.size > 0) {
          audioChunksRef.current.push(event.data);

          // Progressive Upload: Stream audio chunk to backend in real-time
          const currentChunkIndex = chunkIndex++;
          const formData = new FormData();
          formData.append("chunk", event.data, `chunk_${currentChunkIndex}.webm`);
          formData.append("meetingId", meetingId);
          formData.append("chunkIndex", currentChunkIndex.toString());

          fetch("/api/recordings/stream-chunk", {
            method: "POST",
            body: formData,
          })
            .then(async (res) => {
              if (res.ok) {
                const data = await res.json();
                if (data.segment) {
                  setAgent((prev) => ({
                    ...prev,
                    transcript: [...(prev.transcript || []), data.segment],
                  }));
                }
              }
            })
            .catch(() => {});
        }
      };

      recorder.onstop = async () => {
        const audioBlob = new Blob(audioChunksRef.current, { type: recorder.mimeType || "audio/webm" });
        stream.getTracks().forEach((track) => track.stop());

        setIsTabRecording(false);
        if (recordTimerRef.current) clearInterval(recordTimerRef.current);

        await uploadAndProcessTabAudio(audioBlob);
      };

      recorder.start(1000);
      setIsTabRecording(true);
      setTabRecordSeconds(0);
      setAgent((prev) => ({ ...prev, status: "recording" }));

      recordTimerRef.current = setInterval(() => {
        setTabRecordSeconds((prev) => prev + 1);
      }, 1000);
    } catch (err: any) {
      console.error("Tab audio capture error:", err);
      setErrorMsg("Could not capture tab audio. Please grant screen/audio permissions.");
    }
  };

  const stopTabAudioCapture = () => {
    if (mediaRecorderRef.current && mediaRecorderRef.current.state !== "inactive") {
      mediaRecorderRef.current.stop();
    }
  };

  const handleEndMeeting = async () => {
    if (isTabRecording) {
      stopTabAudioCapture();
      return;
    }

    setLoading(true);
    setErrorMsg(null);
    setAgent((prev: any) => ({ ...prev, status: "completed" }));

    try {
      await Promise.all([
        fetch("/api/ai-agent/leave", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ meetingId }),
        }).catch(() => {}),
        fetch("/api/meeting-baas/leave", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ meetingId }),
        }).catch(() => {}),
      ]);

      await fetchStatus();
      await fetchActionItems();
      await fetchCitations();
    } catch (err: any) {
      setErrorMsg(err.message || "Error ending meeting");
    } finally {
      setLoading(false);
    }
  };

  return {
    agent,
    actionItems,
    citations,
    highlightedChunkIndex,
    setHighlightedChunkIndex,
    loading,
    errorMsg,
    userRole,
    customMeetUrl,
    setCustomMeetUrl,
    audioQuality,
    setAudioQuality,
    isTabRecording,
    tabRecordSeconds,
    handleManagedBotJoin,
    handleEndMeeting,
    startTabAudioCapture,
    stopTabAudioCapture,
    fetchStatus,
    fetchActionItems,
    fetchCitations,
  };
}

audio-validator.ts.content:
/**
 * Comprehensive Audio Validation Utility
 * Validates file buffer size, magic bytes, header integrity, and minimum duration.
 */

export interface AudioValidationResult {
  valid: boolean;
  error?: string;
  mimeType?: string;
  byteSize: number;
  estimatedDurationSeconds?: number;
}

export function validateAudioBuffer(
  buffer: Buffer,
  mimeTypeHint: string = "audio/wav"
): AudioValidationResult {
  const byteSize = buffer ? buffer.length : 0;

  // 1. Check for null or empty buffer
  if (!buffer || byteSize === 0) {
    return {
      valid: false,
      error: "Audio payload is empty (0 bytes).",
      byteSize: 0,
    };
  }

  // 2. Minimum byte threshold (WAV header alone is 44 bytes; usable audio must exceed 100 bytes)
  if (byteSize < 100) {
    return {
      valid: false,
      error: `Audio payload is too small (${byteSize} bytes) to contain usable audio stream data.`,
      byteSize,
    };
  }

  // 3. Inspect Magic Bytes / File Signatures
  let detectedType = mimeTypeHint;
  const isWav = buffer.toString("ascii", 0, 4) === "RIFF" && buffer.toString("ascii", 8, 12) === "WAVE";
  const isWebm = buffer[0] === 0x1a && buffer[1] === 0x45 && buffer[2] === 0xdf && buffer[3] === 0xa3;
  const isOgg = buffer.toString("ascii", 0, 4) === "OggS";
  const isMp3 = (buffer[0] === 0x49 && buffer[1] === 0x44 && buffer[2] === 0x33) || (buffer[0] === 0xff && (buffer[1] & 0xe0) === 0xe0);
  const isFlac = buffer.toString("ascii", 0, 4) === "fLaC";

  if (isWav) detectedType = "audio/wav";
  else if (isWebm) detectedType = "audio/webm";
  else if (isOgg) detectedType = "audio/ogg";
  else if (isMp3) detectedType = "audio/mpeg";
  else if (isFlac) detectedType = "audio/flac";

  // 4. Estimate Duration & Validate Content
  let estimatedDuration = 0;

  if (isWav && byteSize > 44) {
    // Standard 16kHz Mono 16-bit PCM WAV has 32,000 bytes per second
    const byteRate = buffer.readUInt32LE(28) || 32000;
    const dataSize = byteSize - 44;
    estimatedDuration = Math.max(0, Math.round((dataSize / byteRate) * 10) / 10);
  } else {
    // Rough estimation for compressed audio streams
    estimatedDuration = Math.max(1, Math.round((byteSize / 16000) * 10) / 10);
  }

  // 5. Fail validation if WAV file contains only empty failsafe headers (e.g. exactly 44 bytes or <0.5s duration)
  if (estimatedDuration < 0.2 && isWav) {
    return {
      valid: false,
      error: `Audio recording duration (${estimatedDuration}s) is below minimum transcription threshold (0.5s).`,
      mimeType: detectedType,
      byteSize,
      estimatedDurationSeconds: estimatedDuration,
    };
  }

  return {
    valid: true,
    mimeType: detectedType,
    byteSize,
    estimatedDurationSeconds: estimatedDuration,
  };
}

