            >
              <Radio className="w-4 h-4 animate-pulse" />
              <span>HOST INSTANT MEETING</span>
            </button>
          </div>
        )}

        {/* Navigation Items */}
        <nav className="px-3 space-y-1 mt-1 font-sans">
