import { NextResponse } from "next/server";
import { db } from "@/lib/db";
import { triggerAIAgent } from "@/lib/ai-agent-engine";

export async function POST(req: Request) {
  try {
    const body = await req.json().catch(() => ({}));
    const { title, department, googleMeetLink, agenda } = body;

    const meetingTitle = title || `Instant AI Meeting (${new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })})`;
    const meetingDepartment = department || "Engineering";
    const meetingAgenda = googleMeetLink || agenda || "Instant AI Notetaker session launched by user.";

    // 1. Create instant Meeting record with "In Progress" status
    const meeting = await db.meeting.create({
      data: {
        title: meetingTitle,
        department: meetingDepartment,
        agenda: meetingAgenda,
        status: "In Progress",
        date: new Date(),
      },
    });

    // 2. Trigger Playwright Bot asynchronously
    triggerAIAgent(meeting.id).catch((err) =>
      console.warn(`[POST /api/meetings/host] Async bot trigger failed for ${meeting.id}:`, err)
    );

    return NextResponse.json({
      message: "Instant meeting created successfully",
      meetingId: meeting.id,
      status: meeting.status,
    });
  } catch (error: any) {
    console.error("[POST /api/meetings/host]", error);
    return NextResponse.json(
      { error: error.message || "Failed to host instant meeting" },
      { status: 500 }
    );
  }
}

ModalPortal.tsx.content:
"use client";

import { useEffect, useState } from "react";
import { createPortal } from "react-dom";
import { useScrollLock } from "@/hooks/useScrollLock";

interface ModalPortalProps {
  isOpen: boolean;
  onClose: () => void;
  title?: string;
  children: React.ReactNode;
}

export function ModalPortal({ isOpen, onClose, title, children }: ModalPortalProps) {
  const [mounted, setMounted] = useState(false);

  // Lock background scrolling when modal is active
  useScrollLock(isOpen);

  useEffect(() => {
    setMounted(true);
  }, []);

  // Listen for Escape key press to dismiss modal
  useEffect(() => {
    if (!isOpen) return;

    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        onClose();
      }
    };

    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, [isOpen, onClose]);

  if (!mounted || !isOpen) return null;

  return createPortal(
    <div
      className="fixed inset-0 z-50 flex items-center justify-center p-4 bg-black/50 backdrop-blur-xs animate-fadeIn"
      role="dialog"
      aria-modal="true"
      aria-label={title || "Modal Dialog"}
      onClick={(e) => {
        // Dismiss when clicking directly on overlay backdrop
        if (e.target === e.currentTarget) {
          onClose();
        }
      }}
    >
      <div className="relative w-full max-w-lg max-h-[90vh] overflow-y-auto">
        {children}
      </div>
    </div>,
    document.body
  );
}

useScrollLock.ts.content:
"use client";

import { useEffect } from "react";

export function useScrollLock(lock: boolean) {
  useEffect(() => {
    if (!lock) return;

    // Save initial overflow and paddingRight to restore on unlock
    const originalStyle = window.getComputedStyle(document.body).overflow;
    const originalPadding = document.body.style.paddingRight;

    // Calculate scrollbar width to prevent visual layout shift
    const scrollbarWidth = window.innerWidth - document.documentElement.clientWidth;

    document.body.style.overflow = "hidden";
    if (scrollbarWidth > 0) {
      document.body.style.paddingRight = `${scrollbarWidth}px`;
    }

    return () => {
      document.body.style.overflow = originalStyle;
      document.body.style.paddingRight = originalPadding;
    };
  }, [lock]);
}
